import java.text.Normalizer;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * A filter over the customer list.
 *
 * <p>A customer matches when its status is one of {@link #statuses} (or
 * {@link #statuses} is empty) and every whitespace-separated term in
 * {@link #name} appears, case- and accent-insensitively, as a substring of
 * either the first or the last name.
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());

    private static final Pattern WHITESPACE = Pattern.compile("\\s+");

    public CustomerFilter {
        name = name == null ? "" : name;
        statuses = statuses == null ? Set.of() : Set.copyOf(statuses);
    }

    public boolean matches(Customer customer) {
        if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
            return false;
        }
        String trimmed = name.trim();
        if (trimmed.isEmpty()) {
            return true;
        }
        String first = normalize(customer.firstName());
        String last = normalize(customer.lastName());
        for (String term : WHITESPACE.split(trimmed)) {
            String needle = normalize(term);
            if (!first.contains(needle) && !last.contains(needle)) {
                return false;
            }
        }
        return true;
    }

    private static String normalize(String s) {
        String decomposed = Normalizer.normalize(s, Normalizer.Form.NFD);
        return decomposed.replaceAll("\\p{M}", "").toLowerCase(Locale.ROOT);
    }
}
