     * Returns the URL of the most recent browser history update, asserting it was a
     * replace (not a push) when {@code expectReplace} is true.
     *
     * <p>Depending on deployment configuration, {@link com.vaadin.flow.component.page.History}
     * either calls {@code window.history.replaceState}/{@code pushState} directly or dispatches
     * a {@code vaadin-navigate} client event carrying a {@code replace} flag; either shape is
     * accepted here.
     */
    private static String lastHistoryUrl(boolean expectReplace) {
        List<PendingJavaScriptInvocation> historyCalls = UI.getCurrent().getInternals()
                .dumpPendingJavaScriptInvocations().stream()
                .filter(invocation -> isHistoryUpdate(invocation.getInvocation().getExpression()))
                .toList();
        assertFalse(historyCalls.isEmpty(), "Expected a history update after the filter changed");

        PendingJavaScriptInvocation last = historyCalls.get(historyCalls.size() - 1);
        if (expectReplace) {
            assertTrue(isReplace(last.getInvocation().getExpression()),
                    "Filter changes must use replaceState, not pushState, so as not to add a history entry per change");
        }
        return (String) last.getInvocation().getParameters().get(1);
    }

    private static boolean isHistoryUpdate(String expression) {
        return expression.contains("history.replaceState") || expression.contains("history.pushState")
                || expression.contains("vaadin-navigate");
    }

    private static boolean isReplace(String expression) {
        return expression.contains("history.replaceState") || expression.contains("replace: true");
