    public String getUrl() {
        return "http://localhost:" + port;
    }

    @Test
    void typingNarrowsTheGridAndUpdatesTheAddressBarWithoutReloading() {
        TextFieldElement nameFilter = new TextFieldElement(page.locator("vaadin-text-field"));
        nameFilter.setValue("mäkinen");

        page.waitForCondition(() -> GridElement.get(page).getTotalRowCount() == 15);
        assertTrue(page.url().contains("name="), "Expected a name parameter in the URL, got: " + page.url());

        // The path must be unchanged: only the query string was updated, no full navigation.
        assertTrue(page.url().startsWith(getUrl()), "Expected the same origin/path, got: " + page.url());
    }

    @Test
    void statusFilterNarrowsTheGrid() {
        MultiSelectComboBoxElement statusFilter =
                MultiSelectComboBoxElement.getByLabel(page, "Status");
        statusFilter.selectItem(CustomerStatus.ACTIVE.name());

        page.waitForCondition(() -> GridElement.get(page).getTotalRowCount() == 167);
        assertTrue(page.url().contains("status=ACTIVE"), "Expected a status parameter in the URL, got: " + page.url());
    }

    @Test
    void openingWithQueryParametersPrefillsTheFilterAndNarrowsTheGrid() {
        page.navigate(getUrl() + "/?name=vir&status=ACTIVE,CLOSED");
        page.waitForFunction(
                "() => {if (window.Vaadin && window.Vaadin.Flow && window.Vaadin.Flow.clients) {"
                        + " var clients = window.Vaadin.Flow.clients; for (var c in clients) {"
                        + " if (clients[c].isActive()) { return false; } } return true; } return true;}");

        TextFieldElement nameFilter = new TextFieldElement(page.locator("vaadin-text-field"));
        assertEquals("vir", nameFilter.getValue());

        MultiSelectComboBoxElement statusFilter =
                MultiSelectComboBoxElement.getByLabel(page, "Status");
        assertEquals(2, statusFilter.getSelectedItemCount());

        page.waitForCondition(() -> GridElement.get(page).getTotalRowCount() < 500);
        assertFalse(GridElement.get(page).getTotalRowCount() == 500);
    }
}
